namespace Sts2CharForge.Core.Generation;

/// <summary>V0.3.108：自定义状态 tooltip 的运行时补丁源码。</summary>
public static class PowerHoverPatchGen
{
    public const string FileName = "ForgePowerHoverPatch";

    public static string Source(string ns) => Template.Replace("__NS__", ns, StringComparison.Ordinal);

    private const string Template = """
// <auto-generated> V0.3.111：自定义状态悬停说明补丁（直接用场上实例，按当前层数重建 Description） </auto-generated>
using System;
using System.Collections.Generic;
using HarmonyLib;
using MegaCrit.Sts2.Core.HoverTips;
using MegaCrit.Sts2.Core.Localization;
using MegaCrit.Sts2.Core.Models;

namespace __NS__;

/// <summary>标记：这个状态类的 Description 里有按层数算出来的值，需要补丁重建。</summary>
public interface IForgePowerHover
{
}

/// <summary>
/// 状态图标悬停走 PowerModel.HoverTips。本体在 canonical 模型上取 Description，
/// 随后才把 Amount 改成 1；所以描述里的 {=Amount*2} 会先算成 0。
///
/// 这里以最高优先级直接接管：用**场上实例** __instance 的 Description（只读，不创建副本、
/// 不调用 SetAmount，避免触发第三方 SetAmount 补丁的 NullReferenceException），
/// 再补 singleStarIcon / energyPrefix，最后跳过原方法与低优先级补丁。
/// </summary>
[HarmonyPatch(typeof(PowerModel), nameof(PowerModel.HoverTips), MethodType.Getter)]
[HarmonyPriority(Priority.First)]
internal static class ForgePowerHoverPatch
{
    private static bool Prefix(PowerModel __instance, ref IEnumerable<IHoverTip> __result)
    {
        try
        {
            if (__instance is not IForgePowerHover) return true;
            if (!__instance.IsVisible) return true;

            LocString description = __instance.Description;
            description.Add("singleStarIcon", "[img]res://images/packed/sprite_fonts/star_icon.png[/img]");
            description.Add("energyPrefix", MegaCrit.Sts2.Core.Helpers.EnergyIconHelper.GetPrefix(__instance));

            string text = description.GetFormattedText();
            if (string.IsNullOrWhiteSpace(text)) return true;

            var tips = new List<IHoverTip>
            {
                new HoverTip(__instance, text, isSmart: true),
            };
            tips.AddRange(__instance.GetExtraHoverTips());
            __result = tips;
            return false;
        }
        catch
        {
            // 任何意外都交回原逻辑，绝不把提示弄没
            return true;
        }
    }
}
""";
}
